import Model from 'flarum/common/Model';
export default class BannedIP extends Model {
  creator = Model.hasOne('creator');
  user = Model.hasOne('user');
  address = Model.attribute('address');
  reason = Model.attribute('reason');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  deletedAt = Model.attribute('deletedAt', Model.transformDate);
  apiEndpoint() {
    return `/banned_ips${this.exists ? `/${this.id()}` : ''}`;
  }
}
flarum.reg.add('fof-ban-ips', 'common/models/BannedIP', BannedIP);