import app from 'flarum/common/app';
import { BooleanGambit } from 'flarum/common/query/IGambit';
export default class IPBannedGambit extends BooleanGambit {
  key() {
    return app.translator.trans('fof-ban-ips.lib.gambits.users.ipbanned.key', {}, true);
  }
  canonicalKey() {
    return 'ipbanned';
  }
  filterKey() {
    return 'ipbanned';
  }
  enabled() {
    return !!app.session.user && !!app.forum.attribute('canViewIPBans');
  }
}
flarum.reg.add('fof-ban-ips', 'common/query/users/IPBannedGambit', IPBannedGambit);